// CSD_RATIONALE_BEGIN
// Root-cause of 0% accuracy in attempt 69:
//   `RenderedEndsWith(generated, "<<")` fires on every `<<` the model writes
//   (including space-prefixed `" <<"` variants the Qwen tokenizer produces).
//   The expression parser accepts single variable names (e.g. `["n"]`) as
//   complete expressions, so `IsCompletePrefix(["n"])` is immediately true.
//   We close after 1 token, producing 18 spans of avg 1.15 tokens per example.
//   The evaluator's last span is a bare variable like `<<n>>` → 0% accuracy.
//
// Fix strategy:
//   1. Add a minimum span length guard (`|currentConstrainedOut| >= 2`) before
//      `IsCompletePrefix` triggers eager close. This gives the constrained LM a
//      chance to extend `n` → `n * bill - (m * p1 + k * p2)` using the
//      arithmetic operators that the grammar accepts as valid extensions of a
//      complete sub-expression.
//   2. Update guidance to strongly discourage wrapping individual variables; ask
//      the model to write ONE combined expression per step.
//   3. Keep `RenderedEndsWith` for delimiter detection (required) and all other
//      proven safety mechanisms (budget-pressure force-open, CloseSpanWithinBudget,
//      AdaptiveConstrainedStep with group boosts).
//   4. On EOS while inside a span that is complete, close cleanly before breaking.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside / UnconstrainedStep + EnterObservedConstrainedSpan branch:
//     Sets currentConstrainedOut := [] ; parser.IsValidPrefix([]) holds by
//     method pre-condition. ✓
//   Outside / force-open (OpenConstrainedSpan) branch:
//     Same: currentConstrainedOut := [], parser.IsValidPrefix([]) holds. ✓
//   CloseConstrainedSpan branch (complete & len >= 2):
//     Sets insideConstrainedOut := false, making the implication vacuous;
//     currentConstrainedOut cleared to []. ✓
//   CloseSpanWithinBudget branch (budget pressure / EOS-complete):
//     Postcondition directly guarantees
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). ✓
//   AdaptiveConstrainedStep + AppendConstrainedToken branch:
//     AdaptiveConstrainedStep hard-masks to parser-valid next tokens plus EOS.
//     Non-EOS next satisfies IsTokenValidNext; AppendConstrainedToken extends
//     currentConstrainedOut by that valid token, preserving IsValidPrefix. ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Init: equality at steps == 0. ✓
//   UnconstrainedStep / append branch: steps += 1, generated += 1 token. ✓
//   UnconstrainedStep / EOS break: steps += 1, generated unchanged. ✓
//   OpenConstrainedSpan (force-open): steps += 1, generated += 1 (`<<`). ✓
//   CloseConstrainedSpan: steps += 1, generated grows by at most 1 (`>>`). ✓
//   CloseSpanWithinBudget (closeBudget = maxSteps - steps):
//     |generatedOut| <= |generated| + closeBudget. After steps := maxSteps:
//     |generated| <= |generatedPrefix| + maxSteps == |generatedPrefix| + steps. ✓
//   AdaptiveConstrainedStep + AppendConstrainedToken: steps += 1,
//     generated grows by 1. ✓
//   EOS-inside-complete + CloseConstrainedSpan path: steps already += 1 for
//     AdaptiveConstrainedStep; we use CloseSpanWithinBudget with
//     remaining budget so |generated| stays bounded by |generatedPrefix| + steps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve this math word problem step by step. " +
  "Write each arithmetic expression inside << >> delimiters. " +
  "ALWAYS combine ALL terms into ONE expression inside a single << >>. " +
  "Example: <<n * 5 + k * 3 - d>>  NOT  <<n>> * <<5>> + <<k>> * <<3>>. " +
  "The final << >> must contain the complete answer formula with all variables combined.");

var steps: nat := 0;
var narrowThreshold: nat := 12;
var minSpanLen: nat := 2;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if maxSteps - steps <= 4 && steps > 0 {
      // Budget pressure: force open a constrained span for the final answer.
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        if RenderedEndsWith(generated, "<<") {
          generated, insideConstrainedOut, currentConstrainedOut :=
            helpers.EnterObservedConstrainedSpan(lm, generated);
        }
      }
    }
  } else {
    // Inside a constrained span.
    if maxSteps - steps <= 3 {
      // Near budget end: drive span to completable state and close it.
      var closeBudget := maxSteps - steps;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
    } else if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLen {
      // Span is complete and long enough: close it eagerly.
      var cg, ci, cc := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else {
      // Generate the next constrained token (or extend a short complete prefix).
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        // EOS inside span: if complete, close cleanly within remaining budget.
        if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
          var closeBudget := maxSteps - steps;
          var cg, ci, cc := helpers.CloseSpanWithinBudget(
            lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
          );
          generated := cg;
          insideConstrainedOut := ci;
          currentConstrainedOut := cc;
          steps := maxSteps;
        }
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

